style.css:
@-moz-document domain("userstyles.org"), domain("userstyles.world"), domain("stylish.com") {
body {
        /* A imagem abaixo é o código da sua foto convertida */
        background-image: url("https://r2.erweima.ai/i/Gw2NWgoXcAAPGgT.jfif") !important;
        background-attachment: fixed !important;
        background-size: cover !important;
        background-position: center !important;
        background-repeat: no-repeat !important;

        /* Cores baseadas na paleta da imagem */
        background-color: #6377b8 !important;
        color: #cbe0f7 !important;
        font-family: 'Segoe UI', Tahoma, Geneva, Verdana, sans-serif;
    }

    /* Adicionei uma camada de vidro para os textos não sumirem no fundo claro */
    section, div#main, .container, .content-card {
        background-color: rgba(40, 50, 90, 0.6) !important;
        backdrop-filter: blur(8px) !important;
        border-radius: 12px !important;
        border: 1px solid rgba(203, 224, 247, 0.2) !important;
        padding: 15px !important;
    }

    a {
        color: #d1b3ff !important; /* Um lilás para destacar nos links */
        text-shadow: 0 0 5px rgba(0,0,0,0.5);
        text-decoration: none !important;
        font-weight: bold;
    }

    a:hover {
        color: #ffffff !important;
        text-decoration: underline !important;
    }
}
